function drawArcanineCloudLion(ctx, cx, cy, scale, t, blink = false) {
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const breathPhase = t * 2.0;
  const breathSin = Math.sin(breathPhase);
  const sY = 1.0 + 0.04 * breathSin;
  const sX = 1.0 - 0.02 * breathSin;
  const by = -Math.abs(breathSin) * 2.5;

  const maneLag = breathPhase - 0.45;
  const maneSwayX = Math.sin(maneLag) * 3.0;

  // 1. Bóng sàn
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.ellipse(0, 42, 34 * (1.0 - 0.15 * breathSin), 6, 0, 0, Math.PI * 2); ctx.fill();

  // 2. Đuôi mây cuộn
  const tx = 18 + maneSwayX;
  const ty = by - 6;
  ctx.fillStyle = '#fde047';
  ctx.beginPath(); ctx.arc(tx, ty, 12, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#fef9c3';
  ctx.beginPath(); ctx.arc(tx + 4,  ty - 4,  13, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(tx + 12, ty - 12, 10, 0, Math.PI * 2); ctx.fill();

  // 3. Thân & Sọc
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.ellipse(-2, by + 12, 16 * sX, 13 * sY, 0, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.moveTo(4,  by + 8); ctx.lineTo(8,  by + 18); ctx.lineTo(2,  by + 16); ctx.fill();
  ctx.beginPath(); ctx.moveTo(10, by + 8); ctx.lineTo(14, by + 18); ctx.lineTo(8,  by + 16); ctx.fill();

  // 4. 4 Chân & Lông mây chân
  ctx.fillStyle = '#f97316';
  [-16, -8, 4, 12].forEach(x => {
    ctx.beginPath(); ctx.roundRect(x, by + 18, 6, 17, 2); ctx.fill();
  });
  ctx.fillStyle = '#fef9c3';
  [-13, -5, 7, 15].forEach(x => {
    ctx.beginPath(); ctx.arc(x, by + 34, 4, 0, Math.PI * 2); ctx.fill();
  });

  // 5. Bờm mây ngực & cổ
  ctx.fillStyle = '#fef9c3';
  ctx.beginPath(); ctx.arc(-6, by + 6, 12, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(2,  by + 4, 10, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(-8, by - 6, 11, 0, Math.PI * 2); ctx.fill();

  // 6. Đầu
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.arc(-8, by - 8, 13 * sX, 0, Math.PI * 2); ctx.fill();

  // 7. Chỏm bờm trán
  ctx.fillStyle = '#fef9c3';
  ctx.beginPath(); ctx.moveTo(-16, by - 14); ctx.lineTo(-8, by - 28); ctx.lineTo(0, by - 14); ctx.fill();

  // 8. Tai
  ctx.fillStyle = '#f97316';
  ctx.beginPath(); ctx.moveTo(-18, by - 12); ctx.lineTo(-24, by - 24); ctx.lineTo(-14, by - 16); ctx.fill();
  ctx.beginPath(); ctx.moveTo(0,   by - 12); ctx.lineTo(4,   by - 24); ctx.lineTo(2,   by - 14); ctx.fill();

  // 9. Mõm & Mũi
  ctx.fillStyle = '#fef9c3';
  ctx.beginPath(); ctx.arc(-14, by - 6, 5, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#1e293b';
  ctx.beginPath(); ctx.arc(-15, by - 7, 2, 0, Math.PI * 2); ctx.fill();

  // 10. Mắt
  if (!blink) {
    ctx.beginPath(); ctx.arc(-9, by - 10, 2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(-10, by - 11, 1, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1.2;
    ctx.beginPath(); ctx.moveTo(-11, by - 10); ctx.lineTo(-7, by - 10); ctx.stroke();
  }

  ctx.restore();
}
